import java.io.*; import java.util.*; class Result { public static String isValid(String s) { if (s == null || s.isEmpty()) return "NO"; Map<Character, Integer> charCounts = new HashMap<>(); for (char c : s.toCharArray()) { charCounts.put(c, charCounts.getOrDefault(c, 0) + 1); } Map<Integer, Integer> freqCounts = new HashMap<>(); for (int count : charCounts.values()) { freqCounts.put(count, freqCounts.getOrDefault(count, 0) + 1); } if (freqCounts.size() == 1) return "YES"; if (freqCounts.size() > 2) return "NO"; int[] keys = new int[2]; int[] vals = new int[2]; int i = 0; for (Map.Entry<Integer, Integer> entry : freqCounts.entrySet()) { keys[i] = entry.getKey(); vals[i] = entry.getValue(); i++; } if ((keys[0] == 1 && vals[0] == 1) || (keys[1] == 1 && vals[1] == 1)) return "YES"; if ((keys[0] - keys[1] == 1 && vals[0] == 1) || (keys[1] - keys[0] == 1 && vals[1] == 1)) return "YES"; return "NO"; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); String output = System.getenv("OUTPUT_PATH"); BufferedWriter bufferedWriter = new BufferedWriter(output != null ? new FileWriter(output) : new OutputStreamWriter(System.out)); String s = bufferedReader.readLine(); String result = Result.isValid(s); bufferedWriter.write(result); bufferedWriter.newLine(); bufferedReader.close(); bufferedWriter.close(); } }